package com.campus.lostfound.controller;
import com.campus.lostfound.model.*; import com.campus.lostfound.repository.*; import com.campus.lostfound.service.*; import jakarta.servlet.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*;
@Controller public class WebController {
 private final AuthService auth; private final ItemService itemService; private final UserRepository users; private final HandoverRepository handovers; private final DeletionRequestRepository deletions; private final AuditLogRepository logs;
 public WebController(AuthService a,ItemService i,UserRepository u,HandoverRepository h,DeletionRequestRepository d,AuditLogRepository l){auth=a;itemService=i;users=u;handovers=h;deletions=d;logs=l;}
 private User me(HttpSession s){return (User)s.getAttribute("user");} private String guard(HttpSession s){return me(s)==null?"redirect:/login":null;} private String adminGuard(HttpSession s){User u=me(s);return u==null?"redirect:/login":u.getRole()!=User.Role.ADMIN?"redirect:/dashboard":null;}
 @GetMapping("/") public String home(Model m){m.addAttribute("sampleCount",itemService.browse(null,null,null,null,null).size());return "index";}
 @GetMapping("/login") public String login(){return "login";}
 @PostMapping("/login") public String doLogin(@RequestParam String username,@RequestParam String password,HttpSession s,Model m){User u=auth.login(username,password);if(u==null){m.addAttribute("error","Invalid username or password");return "login";}s.setAttribute("user",u);return "redirect:/dashboard";}
 @PostMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/";}
 @GetMapping("/dashboard") public String dashboard(HttpSession s,Model m,@RequestParam(required=false) String q,@RequestParam(required=false) String type,@RequestParam(required=false) String category,@RequestParam(required=false) String location,@RequestParam(required=false) String status){String g=guard(s);if(g!=null)return g;User u=me(s);m.addAttribute("user",u);m.addAttribute("items",itemService.browse(q,type,category,location,status));m.addAttribute("categories",Category.values());m.addAttribute("statuses",ReportStatus.values());m.addAttribute("q",q);m.addAttribute("type",type);m.addAttribute("category",category);m.addAttribute("location",location);m.addAttribute("status",status);m.addAttribute("myItems",itemService.mine(u));m.addAttribute("matchesCount",itemService.mine(u).stream().mapToInt(i->itemService.matches(i).size()).sum());m.addAttribute("handovers",handovers.findByRequesterOrRecipientOrderByScheduledAtDesc(u,u));m.addAttribute("deletions",deletions.findByRequesterOrderByRequestedAtDesc(u));return "dashboard";}
 @GetMapping("/report") public String report(HttpSession s,Model m){String g=guard(s);if(g!=null)return g;m.addAttribute("categories",Category.values());return "report";}
 @PostMapping("/report") public String create(@RequestParam String type,@RequestParam String itemName,@RequestParam Category category,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE) LocalDate eventDate,@RequestParam String location,@RequestParam String privateDescription,@RequestParam(required=false) MultipartFile photo,HttpSession s,Model m){String g=guard(s);if(g!=null)return g;try{Item i="LOST".equals(type)?new LostItem(itemName,category,eventDate,location,privateDescription,me(s)):new FoundItem(itemName,category,eventDate,location,privateDescription,me(s));if(photo!=null&&!photo.isEmpty()){Path dir=Paths.get("uploads");Files.createDirectories(dir);String name=UUID.randomUUID()+"_"+Path.of(photo.getOriginalFilename()).getFileName();photo.transferTo(dir.resolve(name));i.setPhotoPath("/uploads/"+name);}itemService.save(i,me(s));return "redirect:/dashboard?success=Report submitted";}catch(Exception e){m.addAttribute("error","Could not save report: "+e.getMessage());m.addAttribute("categories",Category.values());return "report";}}
 @GetMapping("/item/{id}") public String item(@PathVariable Long id,HttpSession s,Model m){String g=guard(s);if(g!=null)return g;Optional<Item> oi=itemService.find(id);if(oi.isEmpty())return "redirect:/dashboard";Item i=oi.get();User u=me(s);if(i.getReporter().getId().equals(u.getId())||u.getRole()==User.Role.ADMIN)m.addAttribute("privateAllowed",true);else m.addAttribute("privateAllowed",false);m.addAttribute("item",i);m.addAttribute("matches",itemService.matches(i));m.addAttribute("user",u);return "item";}
 @PostMapping("/item/{id}/handover") public String handover(@PathVariable Long id,@RequestParam String details,@RequestParam String location,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE_TIME) LocalDateTime scheduledAt,HttpSession s){String g=guard(s);if(g!=null)return g;itemService.find(id).ifPresent(i->{if(!i.getReporter().getId().equals(me(s).getId())&&!i.getReporter().getId().equals(me(s).getId())){Handover h=new Handover(i,me(s),i.getReporter(),details,location,scheduledAt);handovers.save(h);i.setStatus(ReportStatus.HANDOVER_PENDING);}});return "redirect:/dashboard?success=Handover request sent";}
 @PostMapping("/handover/{id}/confirm") public String confirm(@PathVariable Long id,HttpSession s){String g=guard(s);if(g!=null)return g;handovers.findById(id).ifPresent(h->{User u=me(s);if(h.getRequester().getId().equals(u.getId()))h.setRequesterConfirmed(true);if(h.getRecipient().getId().equals(u.getId()))h.setRecipientConfirmed(true);if(h.isBothConfirmed()){h.getItem().setStatus(ReportStatus.RETURNED_BY_STUDENTS);itemService.save(h.getItem(),u);}handovers.save(h);});return "redirect:/dashboard?success=Handover confirmation updated";}
 @PostMapping("/item/{id}/delete-request") public String deleteRequest(@PathVariable Long id,@RequestParam String reason,HttpSession s){String g=guard(s);if(g!=null)return g;itemService.find(id).ifPresent(i->{if(i.getReporter().getId().equals(me(s).getId()))deletions.save(new DeletionRequest(i,me(s),reason));});return "redirect:/dashboard?success=Deletion request submitted";}
 @GetMapping("/admin") public String admin(HttpSession s,Model m){String g=adminGuard(s);if(g!=null)return g;m.addAttribute("items",itemService.browse(null,null,null,null,null));m.addAttribute("deletions",deletions.findAll());m.addAttribute("handovers",handovers.findAll());m.addAttribute("logs",logs.findAll());m.addAttribute("user",me(s));return "admin";}
 @PostMapping("/admin/deletion/{id}") public String decision(@PathVariable Long id,@RequestParam String decision,HttpSession s){String g=adminGuard(s);if(g!=null)return g;deletions.findById(id).ifPresent(d->{d.setDecision(decision);deletions.save(d);if("APPROVED".equals(decision))itemService.close(d.getItem(),me(s));logs.save(new AuditLog("DELETION_"+decision,"Request #"+id,me(s)));});return "redirect:/admin";}
 @PostMapping("/admin/handover/{id}/close") public String closeHandover(@PathVariable Long id,HttpSession s){String g=adminGuard(s);if(g!=null)return g;handovers.findById(id).ifPresent(h->{if(h.isBothConfirmed()){h.setAdminClosed(true);handovers.save(h);itemService.close(h.getItem(),me(s));}});return "redirect:/admin";}
}
